CREATE COLUMN TABLE "TEST_AP"."@FORMULAR" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_Description" NVARCHAR(254), "U_ObjType" NVARCHAR(50), "U_TableName" NVARCHAR(254), "U_FieldName" NVARCHAR(100), "U_FieldType" NVARCHAR(10) DEFAULT 'STR', "U_FormularType" NVARCHAR(10) DEFAULT 'UI', "U_DependTable" NVARCHAR(254), "U_DependField" NVARCHAR(100), "U_Formular" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KFORMULAR_NAME" ON "TEST_AP"."@FORMULAR" ( "Name" ASC )